import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import shlex

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
os.makedirs(UPLOAD_DIR, exist_ok=True)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp', 'bmp', 'tiff']

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/convert', methods=['POST'])
def convert_image():
    """Convert uploaded image to target format using ImageMagick."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    target_format = request.form.get('format', 'png').lower().strip()
    if target_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Unsupported format: {target_format}'}), 400

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'Empty filename'}), 400

    safe_name = secure_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(input_path)

    output_name = os.path.splitext(safe_name)[0] + '.' + target_format
    output_path = os.path.join(UPLOAD_DIR, output_name)

    # Build conversion command
    resize = request.form.get('resize', '')
    quality = request.form.get('quality', '85')

    cmd = f'convert {input_path}'

    if resize:
        # Allow geometry strings like "800x600", "50%", etc.
        cmd += f' -resize {resize}'

    cmd += f' -quality {quality} {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )
        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup input
        if os.path.exists(input_path):
            os.unlink(input_path)

    if not os.path.exists(output_path):
        return jsonify({'error': 'Output file not generated'}), 500

    return send_file(output_path, as_attachment=True, download_name=output_name)

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Convert multiple images. Accepts JSON with base64 data."""
    data = request.get_json()
    if not data or 'images' not in data:
        return jsonify({'error': 'No images array'}), 400

    results = []
    for idx, img in enumerate(data['images'][:10]):
        fmt = img.get('format', 'png')
        if fmt not in ALLOWED_FORMATS:
            results.append({'index': idx, 'error': 'bad format'})
            continue
        results.append({'index': idx, 'status': 'queued'})

    return jsonify({'results': results})

@app.route('/metadata', methods=['POST'])
def get_metadata():
    """Extract image metadata using identify command."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file'}), 400

    uploaded = request.files['file']
    safe_name = secure_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(input_path)

    try:
        result = subprocess.run(
            ['identify', '-verbose', input_path],
            capture_output=True,
            timeout=10
        )
        metadata = result.stdout.decode('utf-8', errors='replace')
        return jsonify({'metadata': metadata[:5000]})
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
